<?php require_once __DIR__.'/includes/auth.php';$u=require_login();$type=$_GET['type']??($_POST['type']??'');$id=(int)($_GET['id']??($_POST['id']??0));if(!in_array($type,['provider','business','review'],true)||$id<1){http_response_code(404);include __DIR__.'/404.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$reason=$_POST['reason']??'';$allowed=['fake_profile','wrong_information','spam','fraud_concern','inappropriate_content','other'];if(!in_array($reason,$allowed,true)){flash('error','Please select a valid report reason.');}else{$details=trim((string)($_POST['details']??''));if(text_length($details)>2000){flash('error','Report details are too long.');redirect('report.php?type='.$type.'&id='.$id);} $q=db()->prepare('INSERT INTO reports(reporter_id,target_type,target_id,reason,details) VALUES(?,?,?,?,?)');$q->execute([$u['id'],$type,$id,$reason,$details?:null]);flash('success','Report submitted for admin review.');redirect('report.php?type='.$type.'&id='.$id);}}$pageTitle='Report Content — LocalConnect';require __DIR__.'/includes/header.php';?><div class="container py-5" style="max-width:720px"><h1>Report <?=e($type)?></h1><?php if($m=flash('success')):?><div class="alert alert-success"><?=e($m)?></div><?php endif;?><form method="post" class="card card-body shadow-sm border-0"><?=csrf_field()?><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="id" value="<?=$id?>"><label class="form-label">Reason</label><select name="reason" class="form-select mb-3" required><option value="">Select reason</option><option value="fake_profile">Fake profile</option><option value="wrong_information">Wrong information</option><option value="spam">Spam</option><option value="fraud_concern">Fraud/scam concern</option><option value="inappropriate_content">Inappropriate content</option><option value="other">Other</option></select><label class="form-label">Details</label><textarea name="details" class="form-control mb-3" rows="4" maxlength="2000"></textarea><button class="btn btn-danger">Submit report</button></form></div><?php require __DIR__.'/includes/footer.php';?>